@staticmethod
def _managedCIFSShareName(source:str)->str|None:
    """Vrátí jméno spravovaného share ze zdrojové CIFS cesty."""
    if not smbHelp._isManagedCIFSSource(source):
        return None
    return source.rstrip("/").rsplit("/", 1)[-1]

